function createfigure(yvector1)
%CREATEFIGURE(yvector1)
%  YVECTOR1:  bar yvector

%  Auto-generated by MATLAB on 11-Dec-2023 19:42:12

% Create figure
figure1 = figure;

% Create axes
axes1 = axes('Parent',figure1);
