% Create bar
bar(yvector1,'DisplayName','data1','BarLayout','stacked');

% Create ylabel
ylabel({'∆m_{g,i}'},'FontWeight','bold','FontSize',14);

% Create xlabel
xlabel({'Input variable (I_{i})'},'FontWeight','bold','FontSize',14);

